function BookPage() {
  const servicesQuery = useListPublicServices({ query: { queryKey: getListPublicServicesQueryKey() } });
  const doctorsQuery = useListPublicDoctors(undefined, { query: { queryKey: getListPublicDoctorsQueryKey() } });
  const create = useCreatePublicAppointment();
  const [, setLocation] = useLocation();
  const [submitted, setSubmitted] = useState(false);
  const [form, setForm] = useState({ patientName: '', phone: '', email: '', serviceId: '', doctorId: '', scheduledAt: '', visitType: 'new', notes: '' });
  const services = servicesQuery.data ?? [];
  const doctors = doctorsQuery.data ?? [];
  const update = (key: string, value: string) => setForm((prev) => ({ ...prev, [key]: value }));
  const submit = (event: React.FormEvent) => { event.preventDefault(); if (!form.patientName || !form.phone || !form.email || !form.serviceId || !form.scheduledAt) return; create.mutate({ data: { ...form, doctorId: form.doctorId || null, notes: form.notes || null, visitType: form.visitType as 'new' | 'follow_up' | 'revisit' } }, { onSuccess: (appointment) => { setSubmitted(true); setLocation(`/confirmation/${appointment.id}`); } }); };
  return <div className="min-h-[100dvh] bg-[hsl(var(--background))]"><PublicHeader /><main className="mx-auto max-w-7xl px-5 py-10 lg:px-8 lg:py-16"><div className="mb-10"><Link href="/" data-testid="link-back-home" className="mb-6 inline-flex items-center gap-2 text-sm font-bold text-[hsl(var(--muted-foreground))]"><ChevronRight className="rotate-180" size={15} /> Back to Ashoka Care</Link><p className="text-xs font-bold uppercase tracking-[.2em] text-[hsl(var(--muted-foreground))]">Appointment desk</p><h1 className="mt-3 max-w-xl font-serif text-5xl font-semibold tracking-[-.07em]">Let’s find your<br /><span className="text-[hsl(var(--muted-foreground))]">right next step.</span></h1></div><div className="grid gap-7 lg:grid-cols-[1.2fr_.8fr]"><form onSubmit={submit} className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6 shadow-sm sm:p-8"><div className="mb-7 flex items-center justify-between"><div><h2 className="font-serif text-xl font-semibold">Book a visit</h2><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">Usually takes under two minutes.</p></div><span className="grid h-10 w-10 place-items-center rounded-xl bg-[hsl(var(--secondary)/.35)]"><CalendarDays size={19} /></span></div><div className="grid gap-5 sm:grid-cols-2"><Field label="Your full name" required value={form.patientName} onChange={(e) => update('patientName', e.target.value)} placeholder="e.g. Kavya Sharma" data-testid="input-patient-name" /><Field label="Mobile number" required value={form.phone} onChange={(e) => update('phone', e.target.value)} placeholder="+91 98765 43210" data-testid="input-patient-phone" /><Field label="Email address" type="email" required value={form.email} onChange={(e) => update('email', e.target.value)} placeholder="you@example.com" data-testid="input-patient-email" /><label className="block space-y-1.5"><span className="text-xs font-bold">Visit type</span><select value={form.visitType} onChange={(e) => update('visitType', e.target.value)} data-testid="select-visit-type" className="w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--card))] px-3.5 py-3 text-sm outline-none"><option value="new">First visit</option><option value="follow_up">Follow-up</option><option value="revisit">Revisit</option></select></label><label className="block space-y-1.5 sm:col-span-2"><span className="text-xs font-bold">What would you like help with?</span><select required value={form.serviceId} onChange={(e) => update('serviceId', e.target.value)} data-testid="select-service" className="w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--card))] px-3.5 py-3 text-sm outline-none"><option value="">Select a service</option>{services.map((service) => <option key={service.id} value={service.id}>{service.name}{service.startingPrice ? ` · from ${money(service.startingPrice)}` : ''}</option>)}{!services.length && <option value="general-consultation">General consultation</option>}</select></label><label className="block space-y-1.5"><span className="text-xs font-bold">Preferred specialist <span className="font-normal text-[hsl(var(--muted-foreground))]">(optional)</span></span><select value={form.doctorId} onChange={(e) => update('doctorId', e.target.value)} data-testid="select-doctor" className="w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--card))] px-3.5 py-3 text-sm outline-none"><option value="">No preference</option>{doctors.map((doctor) => <option key={doctor.id} value={doctor.id}>{doctor.name} · {doctor.specialty}</option>)}</select></label><Field label="Preferred date & time" type="datetime-local" required value={form.scheduledAt} onChange={(e) => update('scheduledAt', e.target.value)} data-testid="input-scheduled-at" /><label className="block space-y-1.5 sm:col-span-2"><span className="text-xs font-bold">Anything we should know? <span className="font-normal text-[hsl(var(--muted-foreground))]">(optional)</span></span><textarea value={form.notes} onChange={(e) => update('notes', e.target.value)} data-testid="input-appointment-notes" className="min-h-24 w-full resize-y rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--card))] px-3.5 py-3 text-sm outline-none focus:border-[hsl(var(--secondary))]" placeholder="A short note helps your care team prepare." /></label></div><Button type="submit" disabled={create.isPending || submitted} data-testid="button-submit-booking" className="mt-7 w-full">{create.isPending ? 'Confirming your visit…' : submitted ? 'Appointment confirmed' : <>Confirm appointment <ArrowRight size={16} /></>}</Button>{create.isError && <p data-testid="status-booking-error" className="mt-3 text-sm font-semibold text-red-700">We could not confirm this just now. Please check your details and try again.</p>}</form><aside className="space-y-4"><div className="rounded-2xl bg-[hsl(var(--primary))] p-6 text-white"><p className="text-xs font-bold uppercase tracking-[.2em] text-white/55">Before you arrive</p><ul className="mt-6 space-y-5">{['Bring a photo ID and any previous reports.', 'Arrive 15 minutes before your appointment.', 'Your QR pass works at the front desk.'].map((item) => <li key={item} className="flex gap-3 text-sm leading-6 text-white/75"><Check size={17} className="mt-0.5 shrink-0 text-[hsl(var(--secondary))]" />{item}</li>)}</ul></div><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6"><div className="flex items-center gap-3"><Phone size={18} /><div><p className="text-sm font-bold">Need help choosing?</p><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">Our care navigators are here.</p></div></div><a href="tel:+911140001234" data-testid="link-booking-call" className="mt-5 inline-flex text-sm font-bold underline underline-offset-4">+91 11 4000 1234</a></div></aside></div></main></div>;
}

function ConfirmationPage() {
  const { id } = useParams<{ id: string }>();
  const code = id ? `ASH-${id.slice(-6).toUpperCase()}` : 'ASH-20481';
  return <div className="min-h-[100dvh] bg-[hsl(var(--background))]"><PublicHeader /><main className="mx-auto max-w-4xl px-5 py-12 lg:px-8 lg:py-20"><div className="mx-auto max-w-xl text-center"><div className="mx-auto grid h-16 w-16 place-items-center rounded-2xl bg-[hsl(var(--secondary))]"><BadgeCheck size={30} /></div><p className="mt-6 text-xs font-bold uppercase tracking-[.2em] text-[hsl(var(--muted-foreground))]">Booking confirmed</p><h1 className="mt-3 font-serif text-5xl font-semibold tracking-[-.07em]">You’re on the list.</h1><p className="mt-4 text-sm leading-7 text-[hsl(var(--muted-foreground))]">Keep this pass handy for your visit. We’ve also sent the details to your email.</p></div><div className="relative mx-auto mt-10 max-w-2xl overflow-hidden rounded-[2rem] bg-[hsl(var(--primary))] p-6 text-white shadow-2xl sm:p-8"><div className="absolute -left-8 top-1/2 h-16 w-16 -translate-y-1/2 rounded-full bg-[hsl(var(--background))]" /><div className="absolute -right-8 top-1/2 h-16 w-16 -translate-y-1/2 rounded-full bg-[hsl(var(--background))]" /><div className="flex items-start justify-between border-b border-white/15 pb-6"><div><Logo dark /><p className="mt-5 text-xs font-bold uppercase tracking-[.2em] text-white/45">Appointment pass</p></div><span data-testid="status-confirmed" className="rounded-full bg-[hsl(var(--secondary))] px-3 py-1.5 text-[10px] font-bold uppercase tracking-widest text-[hsl(var(--foreground))]">Confirmed</span></div><div className="grid gap-8 py-8 sm:grid-cols-[1fr_170px] sm:items-center"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-white/45">Confirmation code</p><p data-testid="text-confirmation-code" className="mt-2 font-mono text-2xl font-bold tracking-[.12em]">{code}</p><div className="mt-7 grid grid-cols-2 gap-6"><div><p className="text-xs text-white/45">Patient</p><p data-testid="text-confirmation-patient" className="mt-1 font-semibold">Your appointment</p></div><div><p className="text-xs text-white/45">Check-in</p><p className="mt-1 font-semibold">15 mins early</p></div></div></div><div data-testid="qr-appointment-pass" className="grid aspect-square place-items-center rounded-2xl bg-white p-4"><div className="grid h-full w-full grid-cols-7 grid-rows-7 gap-1">{Array.from({ length: 49 }).map((_, index) => <span key={index} className={cx((index * 17 + 3) % 7 < 3 || [0, 1, 2, 7, 14, 35, 42, 43, 44, 46, 47, 48].includes(index) ? 'bg-[hsl(var(--primary))]' : 'bg-transparent')} />)}</div></div></div><div className="border-t border-white/15 pt-5 text-xs text-white/55">Show this QR code at the Ashoka Care front desk. A valid photo ID may be requested.</div></div><div className="mt-7 flex flex-wrap justify-center gap-3"><Link href="/portal/appointments" data-testid="link-view-appointments" className="inline-flex items-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-5 py-3 text-sm font-bold text-white">View my appointments <ArrowRight size={15} /></Link><Link href="/" data-testid="link-confirmation-home" className="inline-flex items-center gap-2 rounded-xl px-5 py-3 text-sm font-bold text-[hsl(var(--muted-foreground))] hover:bg-[hsl(var(--muted))]">Back to home</Link></div></main></div>;
}

function AuthPage({ mode }: { mode: 'login' | 'register' | 'forgot' }) {
  const isRegister = mode === 'register'; const isForgot = mode === 'forgot';
  const [sent, setSent] = useState(false);
  return <div className="grid min-h-[100dvh] bg-[hsl(var(--background))] lg:grid-cols-[.86fr_1.14fr]"><div className="hidden overflow-hidden bg-[hsl(var(--primary))] p-10 text-white lg:flex lg:flex-col lg:justify-between"><Logo dark /><div className="relative"><div className="absolute -left-20 -top-16 h-72 w-72 rounded-full border border-white/10" /><p className="relative max-w-md font-serif text-5xl font-semibold leading-[.98] tracking-[-.07em]">Your care,<br /><span className="text-[hsl(var(--secondary))]">in one place.</span></p><p className="relative mt-6 max-w-sm text-sm leading-7 text-white/60">Manage visits, access records and stay close to the people looking after you.</p></div><p className="text-xs text-white/45">ASHOKA Care Hospital · Patient services</p></div><div className="flex items-center justify-center px-5 py-10"><div className="w-full max-w-md"><div className="mb-10 lg:hidden"><Logo /></div><Link href="/" data-testid="link-auth-home" className="mb-10 inline-flex items-center gap-2 text-sm font-bold text-[hsl(var(--muted-foreground))]"><ChevronRight className="rotate-180" size={15} /> Ashoka Care</Link><p className="text-xs font-bold uppercase tracking-[.2em] text-[hsl(var(--muted-foreground))]">{isForgot ? 'Account recovery' : 'Patient portal'}</p><h1 className="mt-3 font-serif text-4xl font-semibold tracking-[-.06em]">{isForgot ? 'Reset your password.' : isRegister ? 'Create your account.' : 'Welcome back.'}</h1><p className="mt-3 text-sm leading-6 text-[hsl(var(--muted-foreground))]">{isForgot ? 'Enter your email and we’ll send a secure reset link.' : isRegister ? 'Keep your appointments and health records close.' : 'Sign in to see your care journey.'}</p>{sent ? <div className="mt-8 rounded-2xl border border-[hsl(var(--secondary))] bg-[hsl(var(--secondary)/.25)] p-5"><BadgeCheck size={20} /><p data-testid="status-auth-sent" className="mt-3 font-semibold">Check your inbox for the next step.</p><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">This demo flow is ready for your real auth connection.</p></div> : <form onSubmit={(e) => { e.preventDefault(); setSent(true); }} className="mt-8 space-y-5">{isRegister && <Field label="Full name" required data-testid="input-register-name" placeholder="Your name" />}{!isRegister && !isForgot && <Field label="Patient ID or email" required data-testid="input-login-identity" placeholder="e.g. kavya@email.com" />}{(isRegister || isForgot) && <Field label="Email address" type="email" required data-testid={`input-${mode}-email`} placeholder="you@example.com" />}{isRegister && <Field label="Mobile number" required data-testid="input-register-phone" placeholder="+91 98765 43210" />}{!isForgot && <Field label="Password" type="password" required data-testid={`input-${mode}-password`} placeholder="Enter your password" />}{!isRegister && !isForgot && <div className="text-right"><Link href="/forgot-password" data-testid="link-forgot-password" className="text-xs font-bold underline underline-offset-4">Forgot password?</Link></div>}<Button type="submit" data-testid={`button-submit-${mode}`} className="w-full">{isForgot ? 'Send reset link' : isRegister ? 'Create patient account' : 'Sign in'} <ArrowRight size={15} /></Button></form>}<div className="mt-8 border-t border-[hsl(var(--border))] pt-6 text-center text-sm text-[hsl(var(--muted-foreground))]">{isForgot ? <Link href="/login" data-testid="link-back-login" className="font-bold text-[hsl(var(--foreground))]">Back to sign in</Link> : isRegister ? <>Already have an account? <Link href="/login" data-testid="link-existing-login" className="font-bold text-[hsl(var(--foreground))]">Sign in</Link></> : <>New to Ashoka Care? <Link href="/register" data-testid="link-create-account" className="font-bold text-[hsl(var(--foreground))]">Create an account</Link></>}</div></div></div></div>;
}

function StaffSidebar() {
  const [location, setLocation] = useLocation(); const [mobile, setMobile] = useState(false);
  return <><button data-testid="button-open-sidebar" aria-label="Open navigation" onClick={() => setMobile(true)} className="fixed left-4 top-4 z-40 rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-2.5 shadow-sm lg:hidden"><Menu size={19} /></button><aside className={cx('fixed inset-y-0 left-0 z-50 flex w-[270px] flex-col bg-[hsl(var(--sidebar))] px-4 py-5 text-[hsl(var(--sidebar-foreground))] transition-transform lg:translate-x-0', mobile ? 'translate-x-0' : '-translate-x-full')}><div className="flex items-center justify-between px-2"><Logo dark /><button data-testid="button-close-sidebar" onClick={() => setMobile(false)} className="rounded-lg p-2 text-white/60 hover:bg-white/10 lg:hidden"><X size={18} /></button></div><div className="mt-8 flex-1 overflow-y-auto pr-1">{navGroups.map((group) => <div key={group.label} className="mb-6"><p className="px-3 pb-2 text-[9px] font-bold uppercase tracking-[.2em] text-white/35">{group.label}</p><div className="space-y-0.5">{group.items.map((item) => { const Icon = item.icon; const active = location === item.href; return <Link href={item.href} key={item.href} data-testid={`link-nav-${item.href.slice(1)}`} onClick={() => setMobile(false)} className={cx('flex items-center gap-3 rounded-xl px-3 py-2.5 text-[13px] font-medium transition', active ? 'bg-[hsl(var(--sidebar-accent))] font-bold text-white' : 'text-white/60 hover:bg-white/5 hover:text-white')}><Icon size={16} strokeWidth={active ? 2.4 : 1.8} />{item.label}{item.href === '/notifications' && <span className="ml-auto h-2 w-2 rounded-full bg-[hsl(var(--accent))]" />}</Link>; })}</div></div>)}</div><div className="border-t border-white/10 pt-4"><div className="flex items-center gap-3 rounded-xl px-3 py-2"><span className="grid h-8 w-8 place-items-center rounded-full bg-[hsl(var(--secondary))] text-xs font-bold text-[hsl(var(--foreground))]">AS</span><div className="min-w-0"><p className="truncate text-xs font-bold text-white">Aarav Shah</p><p className="truncate text-[10px] text-white/45">Operations lead</p></div><button data-testid="button-staff-logout" aria-label="Sign out" onClick={() => setLocation('/login')} className="ml-auto text-white/45 hover:text-white"><LogOut size={15} /></button></div></div></aside>{mobile && <button aria-label="Close navigation overlay" data-testid="button-sidebar-overlay" onClick={() => setMobile(false)} className="fixed inset-0 z-40 bg-[hsl(var(--primary)/.45)] lg:hidden" />}</>;
}

function StaffShell({ children }: { children: ReactNode }) {
  return <div className="min-h-[100dvh] bg-[hsl(var(--background))]"><StaffSidebar /><div className="lg:pl-[270px]"><div className="flex h-[72px] items-center justify-between border-b border-[hsl(var(--border))] bg-[hsl(var(--background)/.9)] px-5 backdrop-blur lg:px-9"><div className="pl-12 lg:pl-0"><p className="text-[10px] font-bold uppercase tracking-[.2em] text-[hsl(var(--muted-foreground))]">Ashoka Care / workspace</p><p className="mt-1 text-sm font-semibold">Tuesday, 18 June 2024</p></div><div className="flex items-center gap-2"><button data-testid="button-global-search" aria-label="Search" className="hidden rounded-xl p-2.5 text-[hsl(var(--muted-foreground))] hover:bg-[hsl(var(--muted))] sm:block"><Search size={18} /></button><Link href="/notifications" data-testid="link-header-notifications" className="relative rounded-xl p-2.5 text-[hsl(var(--muted-foreground))] hover:bg-[hsl(var(--muted))]"><Bell size={18} /><span className="absolute right-2 top-2 h-1.5 w-1.5 rounded-full bg-[hsl(var(--accent-foreground))]" /></Link><span className="ml-1 hidden h-8 w-px bg-[hsl(var(--border))] sm:block" /><span className="grid h-8 w-8 place-items-center rounded-full bg-[hsl(var(--accent)/.4)] text-xs font-bold">AS</span></div></div><main className="mx-auto max-w-[1500px] p-5 lg:p-9">{children}</main></div></div>;
}

function PageHeader({ eyebrow, title, detail, action }: { eyebrow: string; title: string; detail?: string; action?: ReactNode }) {
  return <div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="text-[10px] font-bold uppercase tracking-[.2em] text-[hsl(var(--muted-foreground))]">{eyebrow}</p><h1 className="mt-2 font-serif text-4xl font-semibold tracking-[-.06em]">{title}</h1>{detail && <p className="mt-2 max-w-2xl text-sm text-[hsl(var(--muted-foreground))]">{detail}</p>}</div>{action}</div>;
}

function MetricCard({ label, value, change, icon, tone = 'mint' }: { label: string; value: string; change: string; icon: ReactNode; tone?: 'mint' | 'coral' | 'ink' | 'amber' }) {
  return <div className={cx('rounded-2xl border border-[hsl(var(--border))] p-5', tone === 'mint' && 'bg-[hsl(var(--secondary)/.3)]', tone === 'coral' && 'bg-[hsl(var(--accent)/.25)]', tone === 'ink' && 'bg-[hsl(var(--primary))] text-white', tone === 'amber' && 'bg-amber-50')}><div className="flex items-start justify-between"><p className={cx('text-xs font-bold uppercase tracking-[.13em]', tone === 'ink' ? 'text-white/55' : 'text-[hsl(var(--muted-foreground))]')}>{label}</p><span className={cx('grid h-9 w-9 place-items-center rounded-xl', tone === 'ink' ? 'bg-white/10' : 'bg-[hsl(var(--card)/.65)]')}>{icon}</span></div><p data-testid={`metric-${label.toLowerCase().replaceAll(' ', '-')}`} className="mt-7 font-serif text-4xl font-semibold tracking-[-.07em]">{value}</p><p className={cx('mt-2 text-xs font-semibold', tone === 'ink' ? 'text-white/55' : 'text-[hsl(var(--muted-foreground))]')}>{change}</p></div>;
}

function DashboardPage() {
  const query = useGetDashboardSummary({ query: { queryKey: getGetDashboardSummaryQueryKey() } });
  const summary = query.data;
  const appointments = summary?.recentAppointments ?? [];
  return <StaffShell><PageHeader eyebrow="Operations snapshot" title="Good morning, Aarav." detail="Here’s how the hospital is moving today." action={<Button data-testid="button-dashboard-refresh" variant="soft" onClick={() => query.refetch()}><RefreshCw size={15} /> Refresh view</Button>} />{query.isLoading ? <LoadingState /> : <><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Patients today" value={(summary?.totalPatients ?? 128).toLocaleString()} change="+12.4% vs last Tuesday" icon={<Users size={17} />} tone="mint" /><MetricCard label="Appointments" value={(summary?.todaysAppointments ?? 46).toString()} change="8 waiting for check-in" icon={<CalendarDays size={17} />} tone="ink" /><MetricCard label="Emergency cases" value={(summary?.emergencyCases ?? 7).toString()} change="2 high priority" icon={<Zap size={17} />} tone="coral" /><MetricCard label="Bed occupancy" value={`${summary?.occupancy ?? 74}%`} change={`${summary?.pendingAdmissions ?? 3} pending admissions`} icon={<BedDouble size={17} />} tone="amber" /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.3fr_.7fr]"><SectionCard title="Today’s rhythm" action={<Link href="/appointments" data-testid="link-dashboard-appointments" className="text-xs font-bold">View all <ArrowRight className="ml-1 inline" size={13} /></Link>}><div className="divide-y divide-[hsl(var(--border))]">{appointments.length ? appointments.slice(0, 5).map((appointment) => <AppointmentRow key={appointment.id} appointment={appointment} />) : <EmptyState title="No recent appointments" detail="The day is clear for a moment. New bookings will appear here." action={<Link href="/appointments" data-testid="link-empty-appointments" className="text-sm font-bold underline underline-offset-4">Open appointments</Link>} />}</div></SectionCard><SectionCard title="Care flow"><div className="p-5"><div className="flex items-center justify-between"><div><p className="text-4xl font-serif font-semibold tracking-[-.06em]">{money(summary?.revenue ?? 284500)}</p><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">Collected today</p></div><span className="rounded-full bg-[hsl(var(--secondary)/.3)] px-2.5 py-1 text-xs font-bold">+8.6%</span></div><div className="mt-8 space-y-4">{[['Scheduled', summary?.appointmentsByStatus?.scheduled ?? 26, 'bg-[hsl(var(--primary))]'], ['Checked in', summary?.appointmentsByStatus?.checked_in ?? 11, 'bg-[hsl(var(--secondary-foreground))]'], ['In consultation', summary?.appointmentsByStatus?.in_consultation ?? 5, 'bg-[hsl(var(--accent-foreground))]']].map(([label, value, color]) => <div key={String(label)}><div className="mb-1.5 flex justify-between text-xs font-semibold"><span>{label}</span><span>{value}</span></div><div className="h-2 rounded-full bg-[hsl(var(--muted))]"><div className={cx('h-2 rounded-full', String(color))} style={{ width: `${Math.min(100, Number(value) * 2.7)}%` }} /></div></div>)}</div></div></SectionCard></div></>}</StaffShell>;
}

function AppointmentRow({ appointment, onStatus }: { appointment: Appointment; onStatus?: (status: string) => void }) {
  return <div data-testid={`row-appointment-${appointment.id}`} className="flex flex-wrap items-center gap-3 px-5 py-4"><div className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-[hsl(var(--muted))] text-xs font-bold">{initials(appointment.patientName)}</div><div className="min-w-[150px] flex-1"><p data-testid={`text-patient-${appointment.id}`} className="text-sm font-bold">{appointment.patientName}</p><p className="mt-0.5 text-xs text-[hsl(var(--muted-foreground))]">{appointment.doctorName} · {appointment.serviceName}</p></div><div className="text-right text-xs text-[hsl(var(--muted-foreground))]"><p className="font-semibold text-[hsl(var(--foreground))]">{formatDate(appointment.scheduledAt, true)}</p><p className="mt-0.5">{appointment.appointmentNumber}</p></div><StatusPill status={appointment.status} />{onStatus && <select aria-label={`Update status for ${appointment.patientName}`} data-testid={`select-status-${appointment.id}`} value={appointment.status} onChange={(e) => onStatus(e.target.value)} className="rounded-lg border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-2 py-1 text-xs"><option value="scheduled">Scheduled</option><option value="checked_in">Checked in</option><option value="in_consultation">In consultation</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select>}</div>;
}

function PatientsPage() {
  const [search, setSearch] = useState(''); const [showForm, setShowForm] = useState(false); const [created, setCreated] = useState(false);
  const query = useListPatients({ search: search || undefined }, { query: { queryKey: getListPatientsQueryKey({ search: search || undefined }) } }); const create = useCreatePatient();
  const patients = query.data ?? [];
  const submit = (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const formData = new FormData(event.currentTarget); create.mutate({ data: { name: String(formData.get('name')), phone: String(formData.get('phone')), email: String(formData.get('email')), dateOfBirth: String(formData.get('dateOfBirth')), gender: String(formData.get('gender')), bloodGroup: String(formData.get('bloodGroup')) || null } }, { onSuccess: () => { setShowForm(false); setCreated(true); query.refetch(); } }); };
  return <StaffShell><PageHeader eyebrow="Care operations / registry" title="Patients" detail="Find a patient, open their care story or register a new arrival." action={<Button data-testid="button-new-patient" onClick={() => setShowForm(!showForm)}>{showForm ? <X size={16} /> : <Plus size={16} />} {showForm ? 'Close form' : 'Register patient'}</Button>} />{showForm && <form onSubmit={submit} className="mb-5 rounded-2xl border border-[hsl(var(--secondary))] bg-[hsl(var(--secondary)/.16)] p-5"><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><input name="name" required placeholder="Full name" data-testid="input-new-patient-name" className="rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-3 py-2.5 text-sm" /><input name="phone" required placeholder="Phone" data-testid="input-new-patient-phone" className="rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-3 py-2.5 text-sm" /><input name="email" required type="email" placeholder="Email" data-testid="input-new-patient-email" className="rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-3 py-2.5 text-sm" /><input name="dateOfBirth" required type="date" data-testid="input-new-patient-dob" className="rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-3 py-2.5 text-sm" /><select name="gender" data-testid="select-new-patient-gender" className="rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-3 py-2.5 text-sm"><option value="Female">Female</option><option value="Male">Male</option><option value="Other">Other</option></select><input name="bloodGroup" placeholder="Blood group (optional)" data-testid="input-new-patient-blood-group" className="rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-3 py-2.5 text-sm" /><Button type="submit" disabled={create.isPending} data-testid="button-submit-patient">{create.isPending ? 'Saving…' : 'Save patient'}</Button></div></form>}{created && <div data-testid="status-patient-created" className="mb-4 flex items-center gap-2 rounded-xl bg-[hsl(var(--secondary)/.3)] px-4 py-3 text-sm font-semibold"><Check size={16} /> Patient added to the registry.</div>}<SectionCard><div className="flex flex-col gap-3 border-b border-[hsl(var(--border))] p-4 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-3 text-[hsl(var(--muted-foreground))]" size={16} /><input value={search} onChange={(e) => setSearch(e.target.value)} data-testid="input-search-patients" placeholder="Search by name, phone or patient number" className="w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] py-2.5 pl-9 pr-3 text-sm outline-none focus:border-[hsl(var(--secondary))]" /></div><Button data-testid="button-refresh-patients" variant="quiet" onClick={() => query.refetch()}><RefreshCw size={15} /> Refresh</Button></div>{query.isLoading ? <LoadingState /> : patients.length ? <div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="bg-[hsl(var(--muted)/.55)] text-[10px] font-bold uppercase tracking-[.14em] text-[hsl(var(--muted-foreground))]"><tr><th className="px-5 py-3">Patient</th><th className="px-5 py-3">Contact</th><th className="px-5 py-3">Blood group</th><th className="px-5 py-3">Status</th><th className="px-5 py-3">Joined</th></tr></thead><tbody className="divide-y divide-[hsl(var(--border))]">{patients.map((patient) => <tr key={patient.id} data-testid={`row-patient-${patient.id}`} className="transition hover:bg-[hsl(var(--muted)/.4)]"><td className="px-5 py-4"><Link href={`/portal/records?patient=${patient.id}`} data-testid={`link-patient-${patient.id}`} className="flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-xl bg-[hsl(var(--secondary)/.35)] text-xs font-bold">{initials(patient.name)}</span><span><span className="block font-bold">{patient.name}</span><span className="mt-0.5 block text-xs text-[hsl(var(--muted-foreground))]">{patient.patientNumber}</span></span></Link></td><td className="px-5 py-4 text-[hsl(var(--muted-foreground))]">{patient.phone}<br />{patient.email}</td><td className="px-5 py-4 font-bold">{patient.bloodGroup ?? '—'}</td><td className="px-5 py-4"><StatusPill status={patient.status} /></td><td className="px-5 py-4 text-[hsl(var(--muted-foreground))]">{formatDate(patient.createdAt)}</td></tr>)}</tbody></table></div> : <EmptyState title="No patients found" detail={search ? 'Try a different name, phone number or ID.' : 'Patients registered at Ashoka Care will appear here.'} action={<Button data-testid="button-empty-register" onClick={() => setShowForm(true)}><Plus size={15} /> Register first patient</Button>} />}</SectionCard></StaffShell>;
}

function AppointmentsPage() {
  const [statusFilter, setStatusFilter] = useState(''); const query = useListAppointments({ status: statusFilter || undefined }, { query: { queryKey: getListAppointmentsQueryKey({ status: statusFilter || undefined }) } }); const update = useUpdateAppointmentStatus();
  const appointments = query.data ?? [];
  const handleStatus = (id: string, status: string) => update.mutate({ id, data: { status: status as 'scheduled' | 'checked_in' | 'in_consultation' | 'completed' | 'cancelled' | 'no_show' } }, { onSuccess: () => query.refetch() });
  return <StaffShell><PageHeader eyebrow="Care operations / flow" title="Appointments" detail="Keep the day moving with a clear view of every visit." action={<div className="flex gap-2"><select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)} data-testid="select-appointment-status-filter" className="rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--card))] px-3 py-2.5 text-sm"><option value="">All statuses</option><option value="scheduled">Scheduled</option><option value="checked_in">Checked in</option><option value="in_consultation">In consultation</option><option value="completed">Completed</option></select><Button data-testid="button-refresh-appointments" variant="soft" onClick={() => query.refetch()}><RefreshCw size={15} /></Button></div>} /> <SectionCard title={`${appointments.length || 0} visits in view`} action={<span className="text-xs text-[hsl(var(--muted-foreground))]">Live list</span>}>{query.isLoading ? <LoadingState /> : appointments.length ? appointments.map((appointment) => <AppointmentRow key={appointment.id} appointment={appointment} onStatus={(status) => handleStatus(appointment.id, status)} />) : <EmptyState title="The schedule is clear" detail="New appointments will land here as soon as they are booked." action={<Link href="/book" data-testid="link-appointments-booking" className="text-sm font-bold underline underline-offset-4">Open public booking</Link>} />}</SectionCard></StaffShell>;
}

function PatientDetail({ patientId }: { patientId: string }) {
  const patientQuery = useGetPatient(patientId, { query: { queryKey: getGetPatientQueryKey(patientId) } }); const timelineQuery = useGetPatientTimeline(patientId, { query: { queryKey: getGetPatientTimelineQueryKey(patientId) } });
  const patient = patientQuery.data; const timeline = timelineQuery.data ?? [];
  return <div className="grid gap-5 lg:grid-cols-[.75fr_1.25fr]">{patientQuery.isLoading ? <LoadingState /> : <SectionCard><div className="p-5"><div className="grid h-16 w-16 place-items-center rounded-2xl bg-[hsl(var(--secondary)/.35)] font-serif text-2xl font-semibold">{initials(patient?.name)}</div><h2 data-testid="text-patient-detail-name" className="mt-4 font-serif text-2xl font-semibold">{patient?.name ?? 'Patient profile'}</h2><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">{patient?.patientNumber ?? '—'}</p><div className="mt-7 space-y-4 text-sm"><div><p className="text-xs text-[hsl(var(--muted-foreground))]">Phone</p><p className="mt-1 font-semibold">{patient?.phone ?? '—'}</p></div><div><p className="text-xs text-[hsl(var(--muted-foreground))]">Email</p><p className="mt-1 font-semibold">{patient?.email ?? '—'}</p></div><div><p className="text-xs text-[hsl(var(--muted-foreground))]">Blood group</p><p className="mt-1 font-semibold">{patient?.bloodGroup ?? 'Not recorded'}</p></div></div></div></SectionCard>}<SectionCard title="Clinical timeline">{timelineQuery.isLoading ? <LoadingState /> : timeline.length ? <div className="divide-y divide-[hsl(var(--border))]">{timeline.map((event) => <div key={event.id} data-testid={`row-timeline-${event.id}`} className="relative flex gap-4 p-5"><span className="mt-1 grid h-8 w-8 shrink-0 place-items-center rounded-xl bg-[hsl(var(--muted))]"><FileHeart size={15} /></span><div><p className="text-sm font-bold">{event.title}</p><p className="mt-1 text-sm leading-6 text-[hsl(var(--muted-foreground))]">{event.description}</p><p className="mt-2 text-xs font-semibold text-[hsl(var(--muted-foreground))]">{formatDate(event.occurredAt, true)}{event.doctorName ? ` · ${event.doctorName}` : ''}</p></div></div>)}</div> : <EmptyState title="No clinical events yet" detail="This patient’s timeline will build as care is delivered." />}</SectionCard></div>;
}

function PortalShell({ children }: { children: ReactNode }) {
  return <div className="min-h-[100dvh] bg-[hsl(var(--background))]"><PublicHeader /><div className="mx-auto max-w-7xl px-5 py-9 lg:px-8 lg:py-14"><div className="mb-8 flex gap-2 overflow-x-auto border-b border-[hsl(var(--border))] pb-3"><Link href="/portal" data-testid="link-portal-overview" className="whitespace-nowrap rounded-lg px-3 py-2 text-sm font-bold hover:bg-[hsl(var(--muted))]">Overview</Link><Link href="/portal/appointments" data-testid="link-portal-appointments" className="whitespace-nowrap rounded-lg px-3 py-2 text-sm font-bold hover:bg-[hsl(var(--muted))]">Appointments</Link><Link href="/portal/records" data-testid="link-portal-records" className="whitespace-nowrap rounded-lg px-3 py-2 text-sm font-bold hover:bg-[hsl(var(--muted))]">Medical records</Link></div>{children}</div></div>;
}

function PortalOverview() {
  const appointments = useListAppointments(undefined, { query: { queryKey: getListAppointmentsQueryKey() } }); const next = appointments.data?.[0];
  return <PortalShell><PageHeader eyebrow="Patient portal" title="Welcome back, Kavya." detail="A clear view of what’s next in your care." action={<Link href="/book" data-testid="link-portal-book" className="inline-flex items-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-4 py-2.5 text-sm font-bold text-white"><Plus size={15} /> Book a visit</Link>} /><div className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><section className="rounded-2xl bg-[hsl(var(--primary))] p-6 text-white sm:p-8"><p className="text-xs font-bold uppercase tracking-[.2em] text-white/50">Next appointment</p>{next ? <><div className="mt-8 flex items-start justify-between gap-5"><div><p className="font-serif text-3xl font-semibold">{next.serviceName}</p><p className="mt-2 text-sm text-white/65">{next.doctorName} · {next.department}</p></div><StatusPill status={next.status} /></div><div className="mt-10 grid grid-cols-2 gap-4 border-t border-white/15 pt-5"><div><p className="text-xs text-white/45">When</p><p className="mt-1 font-semibold">{formatDate(next.scheduledAt, true)}</p></div><div><p className="text-xs text-white/45">Appointment no.</p><p data-testid="text-portal-appointment-number" className="mt-1 font-semibold">{next.appointmentNumber}</p></div></div><Link href={`/confirmation/${next.id}`} data-testid="link-portal-pass" className="mt-6 inline-flex items-center gap-2 rounded-xl bg-[hsl(var(--secondary))] px-4 py-2.5 text-sm font-bold text-[hsl(var(--foreground))]">Open check-in pass <ArrowRight size={15} /></Link></> : <EmptyState title="Nothing booked yet" detail="Choose a service and take the next step when you’re ready." action={<Link href="/book" data-testid="link-portal-empty-book" className="rounded-xl bg-[hsl(var(--secondary))] px-4 py-2.5 text-sm font-bold text-[hsl(var(--foreground))]">Book now</Link>} />}</section><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-1"><Link href="/portal/records" data-testid="card-portal-records" className="group rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 hover:-translate-y-0.5 hover:shadow-lg"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[hsl(var(--accent)/.3)]"><FileHeart size={18} /></span><h2 className="mt-10 font-serif text-xl font-semibold">Your care story</h2><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">See visits, reports and notes in one timeline.</p><ArrowRight className="mt-5 text-[hsl(var(--muted-foreground))] transition group-hover:translate-x-1" size={17} /></Link><div className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--secondary)/.27)] p-5"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[hsl(var(--card)/.75)]"><Phone size={18} /></span><h2 className="mt-10 font-serif text-xl font-semibold">Need help?</h2><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">Our care desk is available every day.</p><a href="tel:+911140001234" data-testid="link-portal-help" className="mt-5 inline-flex text-sm font-bold underline underline-offset-4">Call the care desk</a></div></div></div></PortalShell>;
}

function PortalAppointments() {
  const [notice, setNotice] = useState(''); const query = useListAppointments(undefined, { query: { queryKey: getListAppointmentsQueryKey() } }); const revisit = useCreateRevisitAppointment();
  const appointments = query.data ?? [];
  const revisitAppointment = (appointment: Appointment) => { const nextDay = new Date(Date.now() + 7 * 86400000).toISOString(); revisit.mutate({ id: appointment.id, data: { scheduledAt: nextDay, doctorId: null, notes: 'Requested from patient portal' } }, { onSuccess: () => { setNotice('Your revisit request is confirmed.'); query.refetch(); } }); };
  return <PortalShell><PageHeader eyebrow="Patient portal / visits" title="Appointments" detail="Your upcoming and previous visits, together." action={<Link href="/book" data-testid="link-appointments-new" className="inline-flex items-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-4 py-2.5 text-sm font-bold text-white"><Plus size={15} /> New appointment</Link>} />{notice && <div data-testid="status-revisit-success" className="mb-5 flex items-center gap-2 rounded-xl bg-[hsl(var(--secondary)/.3)] px-4 py-3 text-sm font-semibold"><Check size={16} /> {notice}</div>}<SectionCard>{query.isLoading ? <LoadingState /> : appointments.length ? appointments.map((appointment) => <div key={appointment.id} className="flex flex-wrap items-center gap-4 border-b border-[hsl(var(--border))] p-5 last:border-0"><div className="grid h-11 w-11 place-items-center rounded-xl bg-[hsl(var(--muted))]"><CalendarDays size={18} /></div><div className="min-w-[180px] flex-1"><p className="font-bold">{appointment.serviceName}</p><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">{appointment.doctorName} · {formatDate(appointment.scheduledAt, true)}</p></div><StatusPill status={appointment.status} /><div className="flex gap-2"><Link href={`/confirmation/${appointment.id}`} data-testid={`link-pass-${appointment.id}`} className="rounded-lg px-3 py-2 text-xs font-bold hover:bg-[hsl(var(--muted))]">Pass</Link><Button data-testid={`button-revisit-${appointment.id}`} variant="soft" disabled={revisit.isPending} onClick={() => revisitAppointment(appointment)}>{revisit.isPending ? 'Requesting…' : 'Book revisit'}</Button></div></div>) : <EmptyState title="No appointments yet" detail="Your confirmed visits will appear here." action={<Link href="/book" data-testid="link-empty-portal-book" className="text-sm font-bold underline underline-offset-4">Find care</Link>} />}</SectionCard></PortalShell>;
}

function PortalRecords() {
  const params = new URLSearchParams(window.location.search); const patientId = params.get('patient') ?? 'demo-patient'; return <PortalShell><PageHeader eyebrow="Patient portal / records" title="Your care story" detail="A simple, secure timeline of the care you’ve received." action={<Button data-testid="button-download-records" variant="soft" onClick={() => window.print()}><Receipt size={15} /> Print summary</Button>} /><PatientDetail patientId={patientId} /></PortalShell>;
}

function GenericModule({ path }: { path: string }) {
  const config: Record<string, { title: string; eyebrow: string; detail: string; icon: ReactNode; items: string[] }> = {
    '/doctors': { title: 'Doctors & staff', eyebrow: 'Care operations / people', detail: 'Know who is on duty, where they are needed and what they are carrying.', icon: <Stethoscope />, items: ['On duty today', 'Specialty coverage', 'Leave & availability'] },
    '/opd': { title: 'OPD', eyebrow: 'Care operations / outpatient', detail: 'Keep the outpatient floor calm, visible and ready for every arrival.', icon: <BriefcaseMedical />, items: ['Waiting room', 'Consultation rooms', 'Queue health'] },
    '/ipd': { title: 'IPD & admissions', eyebrow: 'Care operations / inpatient', detail: 'A live view of beds, admissions and the next handover.', icon: <BedDouble />, items: ['Bed board', 'Pending admissions', 'Discharge planning'] },
    '/emergency': { title: 'Emergency', eyebrow: 'Care operations / high priority', detail: 'Make urgent work visible without adding noise.', icon: <Zap />, items: ['Active cases', 'Triage queue', 'Response teams'] },
    '/emr': { title: 'Medical records', eyebrow: 'Clinical records', detail: 'One clear place for clinical notes, diagnoses and patient timelines.', icon: <FileHeart />, items: ['Recent charts', 'Unsigned notes', 'Care summaries'] },
    '/laboratory': { title: 'Laboratory', eyebrow: 'Clinical records / diagnostics', detail: 'Track specimens from collection to a result someone can act on.', icon: <FlaskConical />, items: ['Specimen queue', 'Results to review', 'Turnaround time'] },
    '/radiology': { title: 'Radiology & X-ray', eyebrow: 'Clinical records / diagnostics', detail: 'Keep imaging requests and reporting moving together.', icon: <TestTube2 />, items: ['Imaging queue', 'Reports pending', 'Equipment status'] },
    '/pharmacy': { title: 'Pharmacy', eyebrow: 'Clinical records / medication', detail: 'See prescriptions, dispensing and what needs a second look.', icon: <Pill />, items: ['Orders to dispense', 'Low stock', 'Pickup queue'] },
    '/billing': { title: 'Billing', eyebrow: 'Support / revenue cycle', detail: 'Make payments and outstanding work easy to understand.', icon: <Receipt />, items: ['Today collected', 'Outstanding', 'Refunds to review'] },
    '/insurance': { title: 'Insurance', eyebrow: 'Support / payer desk', detail: 'Move pre-authorisations and claims with a clear paper trail.', icon: <ShieldCheck />, items: ['Pending approvals', 'Claims in review', 'Documents needed'] },
    '/ot': { title: 'OT & surgery', eyebrow: 'Clinical records / theatre', detail: 'Coordinate theatre time, teams and the details that keep surgery safe.', icon: <Syringe />, items: ['Today’s theatre', 'Pre-op checklist', 'Recovery handover'] },
    '/nursing': { title: 'Nursing', eyebrow: 'Clinical records / ward', detail: 'A shift view built for handovers, rounds and patient comfort.', icon: <HeartPulse />, items: ['Shift handover', 'Rounds due', 'Escalations'] },
    '/blood-bank': { title: 'Blood bank', eyebrow: 'Support / critical supply', detail: 'Know what is available, reserved and needed next.', icon: <Activity />, items: ['Available units', 'Reserved units', 'Requests'] },
    '/inventory': { title: 'Inventory', eyebrow: 'Support / supplies', detail: 'Make the next replenishment visible before it becomes an interruption.', icon: <Package />, items: ['Low stock', 'Recent deliveries', 'Purchase requests'] },
    '/reports': { title: 'Reports & analytics', eyebrow: 'Support / insight', detail: 'Turn the day’s activity into decisions your teams can use.', icon: <ClipboardList />, items: ['Operations report', 'Care quality', 'Revenue view'] },
    '/admin': { title: 'Admin & settings', eyebrow: 'Workspace / configuration', detail: 'Keep people, permissions and the hospital’s operating rules in order.', icon: <Settings />, items: ['Team access', 'Departments', 'System preferences'] },
  };
  const content = config[path] ?? { title: 'Workspace', eyebrow: 'Ashoka Care', detail: 'A focused workspace for the people who keep care moving.', icon: <Hospital />, items: ['Today', 'Needs attention', 'Recently completed'] };
  const notifications = useListNotifications({ query: { queryKey: getListNotificationsQueryKey() } });
  const isNotifications = path === '/notifications'; const notificationItems = notifications.data ?? [];
  return <StaffShell><PageHeader eyebrow={content.eyebrow} title={content.title} detail={content.detail} action={<Button data-testid={`button-${path.slice(1)}-action`}><Plus size={15} /> Add update</Button>} />{isNotifications ? <SectionCard title="Recent notifications" action={<Button data-testid="button-mark-notifications" variant="quiet">Mark all read</Button>}>{notifications.isLoading ? <LoadingState /> : notificationItems.length ? notificationItems.map((item) => <div key={item.id} data-testid={`row-notification-${item.id}`} className="flex gap-4 border-b border-[hsl(var(--border))] p-5 last:border-0"><span className={cx('mt-1 grid h-9 w-9 shrink-0 place-items-center rounded-xl', item.read ? 'bg-[hsl(var(--muted))]' : 'bg-[hsl(var(--secondary)/.4)]')}><Bell size={16} /></span><div className="flex-1"><div className="flex items-start justify-between gap-3"><p className="text-sm font-bold">{item.title}</p>{!item.read && <span className="mt-1 h-2 w-2 rounded-full bg-[hsl(var(--accent-foreground))]" />}</div><p className="mt-1 text-sm leading-6 text-[hsl(var(--muted-foreground))]">{item.message}</p><p className="mt-2 text-xs text-[hsl(var(--muted-foreground))]">{formatDate(item.createdAt, true)}</p></div></div>) : <EmptyState title="You’re all caught up" detail="Important updates from your hospital team will appear here." />}</SectionCard> : <div className="grid gap-5 md:grid-cols-3">{content.items.map((item, index) => <SectionCard key={item} className={cx(index === 0 && 'md:col-span-2')}><div className="p-5"><span className="grid h-11 w-11 place-items-center rounded-xl bg-[hsl(var(--secondary)/.3)]">{content.icon}</span><p className="mt-10 text-xs font-bold uppercase tracking-[.16em] text-[hsl(var(--muted-foreground))]">{item}</p><p className="mt-2 font-serif text-4xl font-semibold tracking-[-.07em]">{[12, 4, 7][index] ?? 3}</p><p className="mt-2 text-xs text-[hsl(var(--muted-foreground))]">{index === 0 ? 'Needs your attention today' : 'Updated a few minutes ago'}</p></div></SectionCard>)}</div>}<div className="mt-5 rounded-2xl border border-dashed border-[hsl(var(--border))] bg-[hsl(var(--card)/.45)] p-6"><div className="flex items-start gap-3"><CircleAlert size={17} className="mt-0.5 text-[hsl(var(--muted-foreground))]" /><div><p className="text-sm font-bold">This workspace is ready for your team</p><p className="mt-1 text-sm leading-6 text-[hsl(var(--muted-foreground))]">Connect the next workflow when you’re ready. The layout is intentionally quiet so important work stays visible.</p></div></div></div></StaffShell>;
}

function RoutedErrorBoundary({ children }: { children: ReactNode }) { const [location] = useLocation(); return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>; }

function Router() {
  return <RoutedErrorBoundary><Switch>
    <Route path="/" component={PublicHome} /><Route path="/book" component={BookPage} /><Route path="/confirmation/:id" component={ConfirmationPage} />
    <Route path="/login"><AuthPage mode="login" /></Route><Route path="/register"><AuthPage mode="register" /></Route><Route path="/forgot-password"><AuthPage mode="forgot" /></Route>
    <Route path="/portal" component={PortalOverview} /><Route path="/portal/appointments" component={PortalAppointments} /><Route path="/portal/records" component={PortalRecords} />
    <Route path="/dashboard" component={DashboardPage} /><Route path="/patients" component={PatientsPage} /><Route path="/appointments" component={AppointmentsPage} />
    <Route path="/doctors"><GenericModule path="/doctors" /></Route><Route path="/opd"><GenericModule path="/opd" /></Route><Route path="/ipd"><GenericModule path="/ipd" /></Route><Route path="/emergency"><GenericModule path="/emergency" /></Route><Route path="/emr"><GenericModule path="/emr" /></Route><Route path="/laboratory"><GenericModule path="/laboratory" /></Route><Route path="/radiology"><GenericModule path="/radiology" /></Route><Route path="/pharmacy"><GenericModule path="/pharmacy" /></Route><Route path="/billing"><GenericModule path="/billing" /></Route><Route path="/insurance"><GenericModule path="/insurance" /></Route><Route path="/ot"><GenericModule path="/ot" /></Route><Route path="/nursing"><GenericModule path="/nursing" /></Route><Route path="/blood-bank"><GenericModule path="/blood-bank" /></Route><Route path="/inventory"><GenericModule path="/inventory" /></Route><Route path="/notifications"><GenericModule path="/notifications" /></Route><Route path="/reports"><GenericModule path="/reports" /></Route><Route path="/admin"><GenericModule path="/admin" /></Route>
    <Route component={NotFound} />
  </Switch></RoutedErrorBoundary>;
}

function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;